for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  if proc.stat().st_uid!=os.getuid():continue
  for fd in (proc/'fd').iterdir():
   try:
    target=str(fd.resolve())
    if target not in wanted:continue
    flags=next(x.split()[1] for x in (proc/'fdinfo'/fd.name).read_text().splitlines() if x.startswith('flags:'))
    if int(flags,8)&os.O_ACCMODE: writers.append(dict(pid=int(proc.name),path=target))
   except (OSError,StopIteration):pass
 except OSError:pass
